import { parseBoardCode } from './boardCode';
import type { BoardDescription } from './boardCode';
import { generateDeck } from './deck';
import { SELECTION } from './selection';
import type { Selection } from './selection';

export const MAX_MOVES = 999999;
export const MAX_ELAPSED_MS = 359999999;

export interface Board extends BoardDescription {
  readonly deck: readonly number[];
}

export interface GameState {
  readonly board: Board;
  readonly matched: readonly number[];
  readonly selection: Selection;
  readonly moves: number;
  readonly elapsedMs: number;
  readonly started: boolean;
}

export function createGame(boardCode: string): GameState {
  const description = parseBoardCode(boardCode);
  if (!description) throw new Error('Invalid board code.');
  const board = Object.freeze({ ...description, deck: generateDeck(description) });
  return {
    board, matched: [], selection: { kind: SELECTION.closed },
    moves: 0, elapsedMs: 0, started: false,
  };
}

export function pairCount(state: GameState): number {
  return state.matched.length / 2;
}

export function isWon(state: GameState): boolean {
  return state.matched.length === state.board.deck.length;
}

export function formatTime(elapsedMs: number): string {
  const seconds = Math.floor(elapsedMs / 1000);
  return `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, '0')}`;
}
import { MISMATCH_MS, SELECTION } from './selection';
import { MAX_MOVES } from './state';
import type { GameState } from './state';

export function activateCard(state: GameState, index: number): GameState {
  if (!Number.isInteger(index) || index < 0 || index >= state.board.deck.length) return state;
  if (state.matched.includes(index)) return state;
  const selection = state.selection;
  switch (selection.kind) {
    case SELECTION.mismatch:
      return state;
    case SELECTION.closed:
      return { ...state, started: true, selection: { kind: SELECTION.one, index } };
    case SELECTION.one: {
      if (selection.index === index) return state;
      const moves = Math.min(MAX_MOVES, state.moves + 1);
      if (state.board.deck[selection.index] === state.board.deck[index]) {
        return {
          ...state, moves, matched: [...state.matched, selection.index, index],
          selection: { kind: SELECTION.closed },
        };
      }
      return {
        ...state, moves,
        selection: {
          kind: SELECTION.mismatch, first: selection.index, second: index,
          remainingMs: MISMATCH_MS,
        },
      };
    }
  }
}
import { SELECTION } from './selection';
import { isWon, MAX_ELAPSED_MS } from './state';
import type { GameState } from './state';

export function advanceGame(state: GameState, milliseconds: number): GameState {
  if (!Number.isFinite(milliseconds) || milliseconds <= 0 || !state.started || isWon(state)) {
    return state;
  }
  const elapsedMs = Math.min(MAX_ELAPSED_MS, state.elapsedMs + milliseconds);
  const selection = state.selection;
  switch (selection.kind) {
    case SELECTION.closed:
    case SELECTION.one:
      return elapsedMs === state.elapsedMs ? state : { ...state, elapsedMs };
    case SELECTION.mismatch: {
      const remainingMs = selection.remainingMs - milliseconds;
      return {
        ...state, elapsedMs,
        selection: remainingMs <= 0
          ? { kind: SELECTION.closed }
          : { ...selection, remainingMs },
      };
    }
  }
}
import { parseBoardCode } from './boardCode';
import { hasExactKeys, isNonnegativeInteger, isRecord, parseLimitedJson } from './formatInput';
import { SELECTION } from './selection';
import { decodeSelection } from './snapshotSelection';
import { createGame, isWon, MAX_ELAPSED_MS, MAX_MOVES, pairCount } from './state';
import type { GameState } from './state';

export const SNAPSHOT_VERSION = 1;
export const SNAPSHOT_BYTE_LIMIT = 65536;
const SNAPSHOT_KEYS = ['version', 'boardCode', 'matched', 'selection', 'moves', 'elapsedMs', 'started'];

export function encodeSnapshot(state: GameState): string {
  const selection = state.selection.kind === SELECTION.mismatch
    ? { ...state.selection, remainingMs: Math.max(1, Math.ceil(state.selection.remainingMs)) }
    : state.selection;
  return JSON.stringify({
    version: SNAPSHOT_VERSION, boardCode: state.board.code,
    matched: [...state.matched].sort((first, second) => first - second),
    selection, moves: state.moves, elapsedMs: Math.floor(state.elapsedMs), started: state.started,
  }, null, 2);
}

function decodeMatched(value: unknown, state: GameState): readonly number[] | null {
  if (!Array.isArray(value) || value.length > state.board.deck.length) return null;
  const matched: number[] = [];
  const faces = new Map<number, number>();
  for (const index of value) {
    if (!isNonnegativeInteger(index) || index >= state.board.deck.length || matched.includes(index)) return null;
    const face = state.board.deck[index];
    if (face === undefined) return null;
    matched.push(index);
    faces.set(face, (faces.get(face) ?? 0) + 1);
  }
  return [...faces.values()].every((count) => count === 2) ? matched : null;
}

export function decodeSnapshot(text: string): GameState | null {
  const value = parseLimitedJson(text, SNAPSHOT_BYTE_LIMIT);
  if (!isRecord(value) || !hasExactKeys(value, SNAPSHOT_KEYS)) return null;
  if (value.version !== SNAPSHOT_VERSION || typeof value.boardCode !== 'string') return null;
  if (!parseBoardCode(value.boardCode)) return null;
  if (!isNonnegativeInteger(value.moves) || value.moves > MAX_MOVES) return null;
  if (!isNonnegativeInteger(value.elapsedMs) || value.elapsedMs > MAX_ELAPSED_MS) return null;
  if (typeof value.started !== 'boolean') return null;
  const initial = createGame(value.boardCode);
  const matched = decodeMatched(value.matched, initial);
  if (!matched) return null;
  const state = { ...initial, matched, moves: value.moves, elapsedMs: value.elapsedMs, started: value.started };
  const selection = decodeSelection(value.selection, state);
  if (!selection) return null;
  const result = { ...state, selection };
  if (result.moves < pairCount(result) + (selection.kind === SELECTION.mismatch ? 1 : 0)) return null;
  if (!result.started && (result.moves !== 0 || result.elapsedMs !== 0
    || matched.length !== 0 || selection.kind !== SELECTION.closed)) return null;
  if (result.started && result.moves === 0 && selection.kind !== SELECTION.one) return null;
  if (isWon(result) && selection.kind !== SELECTION.closed) return null;
  return result;
}
import { activateCard } from './activateCard';
import { advanceGame } from './advanceGame';
import { parseBoardCode } from './boardCode';
import { hasExactKeys, isNonnegativeInteger, isRecord, parseLimitedJson } from './formatInput';
import { createGame } from './state';
import type { GameState } from './state';

export const REPLAY_VERSION = 1;
export const REPLAY_BYTE_LIMIT = 1048576;
export const REPLAY_ACTION_LIMIT = 10000;

interface ReplayAction {
  readonly atMs: number;
  readonly index: number;
}

function decodeActions(value: unknown, length: number): readonly ReplayAction[] | null {
  if (!Array.isArray(value) || value.length > REPLAY_ACTION_LIMIT) return null;
  const actions: ReplayAction[] = [];
  let previous = 0;
  for (const action of value) {
    if (!isRecord(action) || !hasExactKeys(action, ['atMs', 'index'])) return null;
    if (!isNonnegativeInteger(action.atMs) || action.atMs < previous) return null;
    if (!isNonnegativeInteger(action.index) || action.index >= length) return null;
    actions.push({ atMs: action.atMs, index: action.index });
    previous = action.atMs;
  }
  return actions;
}

