import { activateCard } from './activateCard';
import { advanceGame } from './advanceGame';
import { parseBoardCode } from './boardCode';
import { hasExactKeys, isNonnegativeInteger, isRecord, parseLimitedJson } from './formatInput';
import { createGame } from './state';
import type { GameState } from './state';

export const REPLAY_VERSION = 1;
export const REPLAY_BYTE_LIMIT = 1048576;
export const REPLAY_ACTION_LIMIT = 10000;

interface ReplayAction {
  readonly atMs: number;
  readonly index: number;
}

function decodeActions(value: unknown, length: number): readonly ReplayAction[] | null {
  if (!Array.isArray(value) || value.length > REPLAY_ACTION_LIMIT) return null;
  const actions: ReplayAction[] = [];
  let previous = 0;
  for (const action of value) {
    if (!isRecord(action) || !hasExactKeys(action, ['atMs', 'index'])) return null;
    if (!isNonnegativeInteger(action.atMs) || action.atMs < previous) return null;
    if (!isNonnegativeInteger(action.index) || action.index >= length) return null;
    actions.push({ atMs: action.atMs, index: action.index });
    previous = action.atMs;
  }
  return actions;
}

export function replayGame(text: string): GameState | null {
  const value = parseLimitedJson(text, REPLAY_BYTE_LIMIT);
  if (!isRecord(value) || !hasExactKeys(value, ['version', 'boardCode', 'actions', 'endMs'])) return null;
  if (value.version !== REPLAY_VERSION || typeof value.boardCode !== 'string') return null;
  if (!parseBoardCode(value.boardCode) || !isNonnegativeInteger(value.endMs)) return null;
  let state = createGame(value.boardCode);
  const actions = decodeActions(value.actions, state.board.deck.length);
  if (!actions) return null;
  let previous = 0;
  for (const action of actions) {
    if (action.atMs > value.endMs) return null;
    state = activateCard(advanceGame(state, action.atMs - previous), action.index);
    previous = action.atMs;
  }
  return advanceGame(state, value.endMs - previous);
}

/work/src/game/activateCard.ts.content:
import { MISMATCH_MS, SELECTION } from './selection';
import { MAX_MOVES } from './state';
import type { GameState } from './state';

export function activateCard(state: GameState, index: number): GameState {
  if (!Number.isInteger(index) || index < 0 || index >= state.board.deck.length) return state;
  if (state.matched.includes(index)) return state;
  const selection = state.selection;
  switch (selection.kind) {
    case SELECTION.mismatch:
      return state;
    case SELECTION.closed:
      return { ...state, started: true, selection: { kind: SELECTION.one, index } };
    case SELECTION.one: {
      if (selection.index === index) return state;
      const moves = Math.min(MAX_MOVES, state.moves + 1);
      if (state.board.deck[selection.index] === state.board.deck[index]) {
        return {
          ...state, moves, matched: [...state.matched, selection.index, index],
          selection: { kind: SELECTION.closed },
        };
      }
      return {
        ...state, moves,
        selection: {
          kind: SELECTION.mismatch, first: selection.index, second: index,
          remainingMs: MISMATCH_MS,
        },
      };
    }
  }
}

/work/src/game/snapshotSelection.ts.content:
import { hasExactKeys, isNonnegativeInteger, isRecord } from './formatInput';
import { MISMATCH_MS, SELECTION } from './selection';
import type { Selection } from './selection';
import type { GameState } from './state';

export function decodeSelection(value: unknown, state: GameState): Selection | null {
  if (!isRecord(value)) return null;
  const eligible = (index: unknown): index is number => isNonnegativeInteger(index)
    && index < state.board.deck.length && !state.matched.includes(index);
  switch (value.kind) {
    case SELECTION.closed:
      return hasExactKeys(value, ['kind']) ? { kind: SELECTION.closed } : null;
    case SELECTION.one:
      return hasExactKeys(value, ['kind', 'index']) && eligible(value.index)
        ? { kind: SELECTION.one, index: value.index } : null;
    case SELECTION.mismatch:
      if (!hasExactKeys(value, ['kind', 'first', 'second', 'remainingMs'])) return null;
      if (!eligible(value.first) || !eligible(value.second) || value.first === value.second) return null;
      if (state.board.deck[value.first] === state.board.deck[value.second]) return null;
      if (!isNonnegativeInteger(value.remainingMs)
        || value.remainingMs < 1 || value.remainingMs > MISMATCH_MS) return null;
      return {
        kind: SELECTION.mismatch, first: value.first, second: value.second,
        remainingMs: value.remainingMs,
      };
    default:
      return null;
  }
}

