import { describe, expect, it } from 'vitest';
import { GRID_SIZES, parseBoardCode } from './boardCode';
import { nextGeneratorState } from './deck';
import { createGame } from './state';

describe('version 1 board codes and generation', () => {
  it('matches independently stated Park-Miller states', () => {
    let state = 1;
    const actual = Array.from({ length: 5 }, () => {
      state = nextGeneratorState(state);
      return state;
    });
    expect(actual).toEqual([16807, 282475249, 1622650073, 984943658, 1144108930]);
  });

  it('matches literal shuffled decks at both seed boundaries', () => {
    expect(createGame('np1-4-1').board.deck).toEqual([6, 7, 0, 5, 2, 2, 0, 5, 3, 7, 1, 6, 4, 4, 1, 3]);
    expect(createGame('np1-4-2147483646').board.deck)
      .toEqual([6, 7, 2, 4, 5, 0, 3, 1, 0, 7, 5, 4, 6, 2, 1, 3]);
  });

  it.each(GRID_SIZES)('deals two copies of every face for %i columns', (size) => {
    const { board } = createGame(`np1-${size}-123456`);
    expect(board.deck).toHaveLength(size * size);
    for (let face = 0; face < size * size / 2; face += 1) {
      expect(board.deck.filter((value) => value === face)).toHaveLength(2);
    }
    expect(Object.isFrozen(board)).toBe(true);
    expect(Object.isFrozen(board.deck)).toBe(true);
  });

  it.each([
    '', 'np2-4-1', 'NP1-4-1', 'np1-04-1', 'np1-4-01', 'np1-4-0',
    'np1-4-2147483647', 'np1-5-1', 'np1-4-1.0', 'np1-4-1e1',
    ' np1-4-1', 'np1-4-1 ', 'np1-4-1\n', 'np1-4-1\r\n',
  ])('rejects noncanonical code %j', (code) => {
    expect(parseBoardCode(code)).toBeNull();
    expect(() => createGame(code)).toThrow('Invalid board code.');
  });
});

/work/src/game/snapshot.test.ts.content:
import { describe, expect, it } from 'vitest';
import { activateCard } from './activateCard';
import { advanceGame } from './advanceGame';
import { decodeSnapshot, encodeSnapshot, SNAPSHOT_BYTE_LIMIT } from './snapshot';
import { createGame } from './state';

const snapshot = {
  version: 1, boardCode: 'np1-4-1', matched: [0, 11],
  selection: { kind: 'mismatch', first: 1, second: 2, remainingMs: 300 },
  moves: 2, elapsedMs: 1500, started: true,
};

describe('version 1 snapshots', () => {
  it('round trips fresh, selected, matched and mismatching states', () => {
    const initial = createGame('np1-4-1');
    const selected = activateCard(initial, 0);
    const matched = activateCard(selected, 11);
    const mismatch = activateCard(activateCard(matched, 1), 2);
    for (const state of [initial, selected, matched, mismatch]) {
      expect(decodeSnapshot(encodeSnapshot(state))).toEqual(state);
    }
  });

  it('accepts the documented snapshot and unordered matched whole pairs', () => {
    const state = decodeSnapshot(JSON.stringify(snapshot));
    expect(state).toMatchObject({ matched: [0, 11], moves: 2, elapsedMs: 1500 });
    expect(state?.selection).toEqual(snapshot.selection);
    expect(decodeSnapshot(JSON.stringify({ ...snapshot, matched: [11, 0] }))).not.toBeNull();
    expect(decodeSnapshot(JSON.stringify({
      ...snapshot, matched: [], selection: { kind: 'closed' }, moves: 100,
    }))).not.toBeNull();
  });

  it('exports fractional active time as whole milliseconds without losing a pending mismatch', () => {
    const mismatch = activateCard(activateCard(createGame('np1-4-1'), 0), 1);
    const state = advanceGame(mismatch, 799.75);
    const restored = decodeSnapshot(encodeSnapshot(state));
    expect(restored?.elapsedMs).toBe(799);
    expect(restored?.selection).toMatchObject({ kind: 'mismatch', remainingMs: 1 });
    expect(state.selection).toMatchObject({ remainingMs: 0.25 });
  });

  it.each([
    { version: 2 }, { extra: 1 }, { boardCode: 'np1-4-1\n' },
    { matched: [0] }, { matched: [0, 0] }, { matched: [0, 1] }, { matched: [-1, 11] },
    { matched: [0, 16] }, { matched: [0.5, 11] }, { matched: '0,11' },
    { moves: 1 }, { moves: -1 }, { moves: 1.5 }, { moves: 1000000 },
    { elapsedMs: -1 }, { elapsedMs: 1.5 }, { elapsedMs: 360000000 },
    { started: false }, { started: 'true' },
    { selection: { kind: 'closed', extra: 1 } },
    { selection: { kind: 'one', index: 0 } },
    { selection: { kind: 'one', index: 16 } },
    { selection: { kind: 'mismatch', first: 1, second: 1, remainingMs: 300 } },
    { selection: { kind: 'mismatch', first: 4, second: 5, remainingMs: 300 } },
    { selection: { kind: 'mismatch', first: 1, second: 2, remainingMs: 0 } },
    { selection: { kind: 'mismatch', first: 1, second: 2, remainingMs: 801 } },
    { selection: { kind: 'mismatch', first: 1, second: 2, remainingMs: 0.5 } },
  ])('rejects inconsistent or unknown snapshot fields %j', (patch) => {
    expect(decodeSnapshot(JSON.stringify({ ...snapshot, ...patch }))).toBeNull();
  });

  it('enforces not-started and started-zero-move constraints and completed selection', () => {
    const initial = createGame('np1-4-1');
    const base: unknown = JSON.parse(encodeSnapshot(initial));
    expect(decodeSnapshot(JSON.stringify({ ...snapshot, matched: [], moves: 0, selection: { kind: 'closed' } })))
      .toBeNull();
    expect(decodeSnapshot(encodeSnapshot({ ...initial, elapsedMs: 1 }))).toBeNull();
    expect(decodeSnapshot(encodeSnapshot({ ...initial, moves: 1 }))).toBeNull();
    expect(decodeSnapshot(JSON.stringify(base))).toEqual(initial);
    const completed = {
      ...initial, matched: Array.from({ length: 16 }, (_, index) => index),
      moves: 8, started: true,
    };
    expect(decodeSnapshot(encodeSnapshot(completed))).toEqual(completed);
    expect(decodeSnapshot(encodeSnapshot({ ...completed, selection: { kind: 'one', index: 0 } }))).toBeNull();
  });

  it('rejects malformed, missing and oversized input by UTF-8 bytes', () => {
    for (const text of ['{', 'null', '[]', '{}', JSON.stringify({ ...snapshot, selection: null })]) {
      expect(decodeSnapshot(text)).toBeNull();
    }
    const valid = encodeSnapshot(createGame('np1-4-1'));
    expect(decodeSnapshot(valid + ' '.repeat(SNAPSHOT_BYTE_LIMIT))).toBeNull();
    expect(decodeSnapshot(valid + ' '.repeat(SNAPSHOT_BYTE_LIMIT - new TextEncoder().encode(valid).length)))
      .not.toBeNull();
  });
});

/work/src/game/transitions.test.ts.content:
import { describe, expect, it } from 'vitest';
import { activateCard } from './activateCard';
import { advanceGame } from './advanceGame';
import { GRID_SIZES } from './boardCode';
import { createGame, formatTime, isWon, MAX_ELAPSED_MS, MAX_MOVES, pairCount } from './state';

describe('turns and active time', () => {
  it('starts at the first eligible reveal and ignores repeated or invalid cards', () => {
    const initial = createGame('np1-4-1');
    expect(advanceGame(initial, 5000)).toBe(initial);
    for (const index of [-1, 16, 0.5, NaN]) expect(activateCard(initial, index)).toBe(initial);
    const first = activateCard(initial, 0);
    expect(first).toMatchObject({ started: true, moves: 0, selection: { kind: 'one', index: 0 } });
    expect(activateCard(first, 0)).toBe(first);
    expect(advanceGame(first, 1250).elapsedMs).toBe(1250);
    expect(initial.selection.kind).toBe('closed');
  });

  it('matches immediately with one move and no further activation on matched cards', () => {
    const initial = createGame('np1-4-1');
    const matched = activateCard(activateCard(initial, 0), 11);
    expect(matched).toMatchObject({ moves: 1, matched: [0, 11], selection: { kind: 'closed' } });
    expect(pairCount(matched)).toBe(1);
    expect(activateCard(matched, 11)).toBe(matched);
    expect(initial.matched).toEqual([]);
  });

  it('blocks mismatch activation until exactly 800 active milliseconds', () => {
    const mismatch = activateCard(activateCard(createGame('np1-4-1'), 0), 1);
    expect(mismatch).toMatchObject({ moves: 1, selection: { kind: 'mismatch', remainingMs: 800 } });
    expect(activateCard(mismatch, 2)).toBe(mismatch);
    const pending = advanceGame(mismatch, 799.5);
    expect(pending.selection).toMatchObject({ kind: 'mismatch', remainingMs: 0.5 });
    expect(advanceGame(pending, 0.5).selection).toEqual({ kind: 'closed' });
    expect(advanceGame(mismatch, 900).elapsedMs).toBe(900);
  });

  it('caps counters while allowing a mismatch to close and subsequent matches', () => {
    const first = { ...activateCard(createGame('np1-4-1'), 0), moves: MAX_MOVES, elapsedMs: MAX_ELAPSED_MS };
    const mismatch = activateCard(first, 1);
    expect(mismatch.moves).toBe(MAX_MOVES);
    const closed = advanceGame(mismatch, Number.MAX_SAFE_INTEGER);
    expect(closed.elapsedMs).toBe(MAX_ELAPSED_MS);
    expect(closed.selection.kind).toBe('closed');
    const match = activateCard(activateCard(closed, 0), 11);
    expect(match.matched).toEqual([0, 11]);
    expect(match.moves).toBe(MAX_MOVES);
  });

  it.each(GRID_SIZES)('finishes a complete %ix%i game and stops its clock', (size) => {
    let state = createGame(`np1-${size}-1`);
    for (let face = 0; face < size * size / 2; face += 1) {
      state = activateCard(state, state.board.deck.indexOf(face));
      state = advanceGame(state, 10);
      state = activateCard(state, state.board.deck.lastIndexOf(face));
    }
    expect(isWon(state)).toBe(true);
    expect(state.moves).toBe(size * size / 2);
    expect(state.elapsedMs).toBe(size * size / 2 * 10);
    expect(advanceGame(state, 10000)).toBe(state);
  });

  it('formats minutes beyond 59 and ignores invalid time advances', () => {
    expect(formatTime(999)).toBe('0:00');
    expect(formatTime(3600000)).toBe('60:00');
    expect(formatTime(MAX_ELAPSED_MS)).toBe('5999:59');
    const first = activateCard(createGame('np1-4-1'), 0);
    for (const delta of [0, -1, NaN, Infinity]) expect(advanceGame(first, delta)).toBe(first);
  });
});

/work/src/game/replay.test.ts.content:
import { describe, expect, it } from 'vitest';
import { replayGame, REPLAY_ACTION_LIMIT, REPLAY_BYTE_LIMIT } from './replay';
import { MAX_ELAPSED_MS } from './state';

const replay = {
  version: 1, boardCode: 'np1-4-1',
  actions: [{ atMs: 0, index: 0 }, { atMs: 0, index: 11 }], endMs: 800,
};

describe('version 1 replays', () => {
  it('runs the documented replay with equal-time actions in array order', () => {
    expect(replayGame(JSON.stringify(replay)))
      .toMatchObject({ matched: [0, 11], moves: 1, elapsedMs: 800, selection: { kind: 'closed' } });
  });

  it('starts elapsed time at the first valid activation', () => {
    expect(replayGame(JSON.stringify({ ...replay, actions: [{ atMs: 200, index: 0 }], endMs: 800 }))?.elapsedMs)
      .toBe(600);
    expect(replayGame(JSON.stringify({ ...replay, actions: [], endMs: 800 }))?.elapsedMs).toBe(0);
  });

  it('resolves exact mismatch expiry before the next action and ignores earlier activation', () => {
    const actions = [
      { atMs: 0, index: 0 }, { atMs: 0, index: 1 },
      { atMs: 799, index: 2 }, { atMs: 800, index: 0 }, { atMs: 800, index: 11 },
    ];
    expect(replayGame(JSON.stringify({ ...replay, actions })))
      .toMatchObject({ moves: 2, matched: [0, 11], elapsedMs: 800, selection: { kind: 'closed' } });
  });

  it('caps elapsed time while accepting safe-integer logical timestamps', () => {
    expect(replayGame(JSON.stringify({ ...replay, endMs: Number.MAX_SAFE_INTEGER }))?.elapsedMs)
      .toBe(MAX_ELAPSED_MS);
    const actions = [{ atMs: Number.MAX_SAFE_INTEGER - 100, index: 0 }];
    expect(replayGame(JSON.stringify({ ...replay, actions, endMs: Number.MAX_SAFE_INTEGER }))?.elapsedMs)
      .toBe(100);
  });

  it.each([
    { version: 2 }, { extra: true }, { boardCode: 'np1-4-0' },
    { actions: null }, { actions: [{ atMs: 0, index: 16 }] },
    { actions: [{ atMs: 0, index: -1 }] }, { actions: [{ atMs: 0, index: 1.5 }] },
    { actions: [{ atMs: -1, index: 0 }] }, { actions: [{ atMs: 0.5, index: 0 }] },
    { actions: [{ atMs: 0, index: 0, extra: 1 }] },
    { actions: [{ atMs: 1, index: 0 }, { atMs: 0, index: 11 }] },
    { endMs: -1 }, { endMs: 0.5 }, { endMs: Number.MAX_SAFE_INTEGER + 1 },
    { actions: [{ atMs: 801, index: 0 }] },
  ])('rejects malformed replay fields %j', (patch) => {
    expect(replayGame(JSON.stringify({ ...replay, ...patch }))).toBeNull();
  });

  it('rejects oversized action lists, files and malformed JSON', () => {
    const actions = Array.from({ length: REPLAY_ACTION_LIMIT + 1 }, () => ({ atMs: 0, index: 0 }));
    expect(replayGame(JSON.stringify({ ...replay, actions }))).toBeNull();
    expect(replayGame(JSON.stringify(replay) + ' '.repeat(REPLAY_BYTE_LIMIT))).toBeNull();
    for (const text of ['null', '{', '[]', '{}']) expect(replayGame(text)).toBeNull();
  });
});

tools.description:
Run JavaScript code to orchestrate/compose tool calls
- Evaluates the provided JavaScript code in a fresh V8 isolate as an async module.
- All nested tools are available on the global `tools` object, for example `await tools.exec_command(...)`. Tool names are exposed as normalized JavaScript identifiers, for example `await tools.mcp__ologs__get_profile(...)`.
- Nested tool methods take either a string or an object as their input argument.
- Nested tools return either an object or a string, based on the description.
- Runs raw JavaScript -- no Node, no file system, no network access, no console.
- Accepts raw JavaScript source text, not JSON, quoted strings, or markdown code fences.
- You may optionally start the tool input with a first-line pragma like `// @exec: {"yield_time_ms": 10000, "max_output_tokens": 1000}`.
- `yield_time_ms` asks `exec` to yield early if the script is still running. Defaults to 30000 ms.
- `max_output_tokens` sets the token budget for direct `exec` results. Defaults to 10000 tokens.
- When the JS code is fully evaluated, the isolate's lifetime ends and unawaited promises are silently discarded.

- Global helpers:
- `exit()`: Immediately ends the current script successfully (like an early return from the top level).
- `text(value: string | number | boolean | undefined | null)`: Appends a text item. Non-string values are stringified with `JSON.stringify(...)` when possible.
- `image(imageUrlOrItem: string | { image_url: string; detail?: "auto" | "low" | "high" | "original" | null } | ImageContent, detail?: "auto" | "low" | "high" | "original" | null)`: Appends an image item. `image_url` should be a base64-encoded `data:` URL. To forward an MCP tool image, pass an individual `ImageContent` block from `result.content`, for example `image(result.content[0])`. MCP image blocks may request detail with `_meta: { "codex/imageDetail": "original" }`. When provided, the second `detail` argument overrides any detail embedded in the first argument.
- `audio(audioUrlOrItem: string | { audio_url: string } | AudioContent)`: Appends an audio item. `audio_url` should be a base64-encoded `data:` URL. To forward an MCP tool audio block, pass an individual `AudioContent` block from `result.content`, for example `audio(result.content[0])`.
- `generatedImage(result: { image_url: string; output_hint?: string })`: Appends an image-generation result and its optional output hint. HTTP(S) URLs are not supported.
- `store(key: string, value: any)`: stores a serializable value under a string key for later `exec` calls in the same session.
- `load(key: string)`: returns the stored value for a string key, or `undefined` if it is missing.
- `notify(value: string | number | boolean | undefined | null)`: immediately injects an extra `custom_tool_call_output` for the current `exec` call. Values are stringified like `text(...)`.
- `setTimeout(callback: () => void, delayMs?: number)`: schedules a callback to run later and returns a timeout id. Pending timeouts do not keep `exec` alive by themselves; await an explicit promise if you need to wait for one.
- `clearTimeout(timeoutId?: number)`: cancels a timeout created by `setTimeout`.
- `ALL_TOOLS`: metadata for the enabled nested tools as `{ name, description }` entries.
- `yield_control()`: yields the accumulated output to the model immediately while the script keeps running.

Some deferred nested tools may be omitted from this description. They are still available on the global `tools` object and listed in `ALL_TOOLS`.
To find one, filter `ALL_TOOLS` by `name` and `description`.

Tool availability can change between calls.

Shared MCP Types:
```ts
type Role = "user" | "assistant";
type MetaObject = Record<string, unknown>;
type Annotations = {
  audience?: Role[];
  priority?: number;
  lastModified?: string;
};
type Icon = {
  src: string;
  mimeType?: string;
  sizes?: string[];
  theme?: "light" | "dark";
};
type TextResourceContents = {
  uri: string;
  mimeType?: string;
  _meta?: MetaObject;
  text: string;
};
type BlobResourceContents = {
  uri: string;
  mimeType?: string;
  _meta?: MetaObject;
  blob: string;
};
type TextContent = {
  type: "text";
  text: string;
  annotations?: Annotations;
  _meta?: MetaObject;
};
type ImageContent = {
  type: "image";
  data: string;
  mimeType: string;
  annotations?: Annotations;
  _meta?: MetaObject;
};
type AudioContent = {
  type: "audio";
  data: string;
  mimeType: string;
  annotations?: Annotations;
  _meta?: MetaObject;
};
type ResourceLink = {
  icons?: Icon[];
  name: string;
  title?: string;
  uri: string;
  description?: string;
  mimeType?: string;
  annotations?: Annotations;
  size?: number;
  _meta?: MetaObject;
  type: "resource_link";
};
type EmbeddedResource = {
  type: "resource";
  resource: TextResourceContents | BlobResourceContents;
  annotations?: Annotations;
  _meta?: MetaObject;
};
type ContentBlock =
  | TextContent
  | ImageContent
  | AudioContent
  | ResourceLink
  | EmbeddedResource;
type CallToolResult<TStructured = { [key: string]: unknown }> = {
  _meta?: MetaObject;
  content: ContentBlock[];
  isError?: boolean;
  structuredContent?: TStructured;
  [key: string]: unknown;
};
```

### `apply_patch`
The `apply_patch` tool can be used to edit files. This is a FREEFORM tool, so do not wrap the patch in JSON.

exec tool declaration:
```ts
declare const tools: { apply_patch(input: string): Promise<unknown>; };
```

### `create_goal`
Create a goal only when explicitly requested by the user or system/developer instructions; do not infer goals from ordinary tasks.
Set token_budget only when an explicit token budget is requested. Fails if an unfinished goal exists; use update_goal only for status.

exec tool declaration:
```ts
declare const tools: { create_goal(args: {
  // Required. The concrete objective to start pursuing. This starts a new active goal when no goal exists or replaces the current goal when it is complete.
  objective: string;
  // Positive token budget for the new goal. Omit unless explicitly requested.
  token_budget?: number;
}): Promise<unknown>; };
```

### `exec_command`
Runs a command in a PTY, returning output or a session ID for ongoing interaction.

exec tool declaration:
```ts
declare const tools: { exec_command(args: {
  // Shell command to execute.
  cmd: string;
  // User-facing approval question for `require_escalated`; omit otherwise.
  justification?: string;
  // True runs the shell with -l/-i semantics; false disables them. Defaults to true.
  login?: boolean;
  // Output token budget. Defaults to 10000 tokens; larger requests may be capped by policy.
  max_output_tokens?: number;
  // Reusable approval prefix for `cmd`, only with `sandbox_permissions: "require_escalated"`; for example ["git", "pull"].
  prefix_rule?: Array<string>;
  // Per-command sandbox override. Defaults to `use_default`; use `require_escalated` for unsandboxed execution.
  sandbox_permissions?: "use_default" | "require_escalated";
  // Shell binary to launch. Defaults to the user's default shell.
  shell?: string;
  // True allocates a PTY for the command; false or omitted uses plain pipes.
  tty?: boolean;
  // Working directory for the command. Defaults to the turn cwd.
  workdir?: string;
  // Wait before yielding output. Defaults to 10000 ms; effective range is 250-30000 ms.
  yield_time_ms?: number;
}): Promise<{
  // Chunk identifier included when the response reports one.
  chunk_id?: string;
  // Process exit code when the command finished during this call.
  exit_code?: number;
  // Approximate token count before output truncation.
  original_token_count?: number;
  // Command output text, possibly truncated.
  output: string;
  // Session identifier to pass to write_stdin when the process is still running.
  session_id?: number;
  // Elapsed wall time spent waiting for output in seconds.
  wall_time_seconds: number;
}>; };
```

### `get_goal`
Get the current goal for this thread, including status, budgets, token and elapsed-time usage, and remaining token budget.

exec tool declaration:
```ts
declare const tools: { get_goal(args: {}): Promise<unknown>; };
```

### `list_mcp_resource_templates`
Lists resource templates provided by MCP servers. Parameterized resource templates allow servers to share data that takes parameters and provides context to language models, such as files, database schemas, or application-specific information. Prefer resource templates over web search when possible.

exec tool declaration:
```ts
declare const tools: { list_mcp_resource_templates(args: {
  // Opaque cursor from a previous list_mcp_resource_templates call; omit for the first page.
  cursor?: string;
  // MCP server name. Omit to list resource templates from every configured server.
  server?: string;
}): Promise<unknown>; };
```

### `list_mcp_resources`
Lists resources provided by MCP servers. Resources allow servers to share data that provides context to language models, such as files, database schemas, or application-specific information. Prefer resources over web search when possible.

exec tool declaration:
```ts
declare const tools: { list_mcp_resources(args: {
  // Opaque cursor from a previous list_mcp_resources call; omit for the first page.
  cursor?: string;
  // MCP server name. Omit to list resources from every configured server.
  server?: string;
}): Promise<unknown>; };
```

### `read_mcp_resource`
Read a specific resource from an MCP server given the server name and resource URI.

exec tool declaration:
```ts
declare const tools: { read_mcp_resource(args: {
  // MCP server name exactly as configured. Must match the 'server' field returned by list_mcp_resources.
  server: string;
  // Resource URI to read. Must be one of the URIs returned by list_mcp_resources.
  uri: string;
}): Promise<unknown>; };
```

### `request_plugin_install`
# Suggest a recommended plugin installation

Use this tool only when all of the following are true:
- The user explicitly asks to use a specific plugin that is not already available in the current context or active `tools` list.
- Tool search has already been exhausted and did not find or make the requested tool callable.
- The plugin is listed in `<recommended_plugins>`.

Do not use it for adjacent capabilities, broad recommendations, or plugins that merely seem useful. Briefly explain why the plugin can help with the current request in `suggest_reason`.

IMPORTANT: DO NOT call this tool in parallel with other tools.

exec tool declaration:
```ts
declare const tools: { request_plugin_install(args: {
  // The parenthesized plugin ID from the `<recommended_plugins>` list.
  plugin_id: string;
  // Concise one-line user-facing reason why this plugin can help with the current request.
  suggest_reason: string;
}): Promise<unknown>; };
```

### `update_goal`
Update the existing goal.
Set status to `paused` only at the user's explicit request to pause this goal, never on your own initiative. Ask if unclear; a later resume revokes that request. Report the returned status and stop goal work. Budget limits take precedence over pausing.
Set status to `complete` only when the objective has actually been achieved and no required work remains.
Set status to `blocked` only when the same blocking condition has repeated for at least three consecutive goal turns, counting the original/user-triggered turn and any automatic continuations, and the agent cannot make meaningful progress without user input or an external-state change.
If the user resumes a goal that was previously marked `blocked`, treat the resumed run as a fresh blocked audit. If the same blocking condition then repeats for at least three consecutive resumed goal turns, set status to `blocked` again.
Once the blocked threshold is satisfied, do not keep reporting that you are still blocked while leaving the goal active; set status to `blocked`.
Do not use `blocked` merely because the work is hard, slow, uncertain, incomplete, or would benefit from clarification.
Do not mark a goal complete merely because its budget is nearly exhausted or because you are stopping work.
You cannot use this tool to resume, budget-limit, or usage-limit a goal; those status changes are controlled by the user or system.
When marking a budgeted goal achieved with status `complete`, report the final token usage from the tool result to the user.

exec tool declaration:
