      }}>
        {GRID_SIZES.map((side) => <option key={side} value={side}>{side}x{side}</option>)}
      </select>
    </label>
    <button type="button" className="new-game" onClick={onNewGame}>New Game</button>
    <button type="button" onClick={onRestart}>Restart</button>
  </div>;
}

