  await expect(live(page)).toHaveText('Invalid board code.');
  await expect(page.getByLabel('Board code', { exact: true })).toHaveValue('np1-04-1');
  await expect(page.getByLabel('Grid size', { exact: true })).toHaveValue('4');
  await expect(page.getByText('Pairs: 1/8', { exact: true })).toBeVisible();
  await loadSnapshot(page, '{"version":1}');
  await expect(page.getByRole('button', { name: 'Load snapshot', exact: true })).toBeFocused();
  await expect(live(page)).toHaveText('Invalid snapshot.');
  await expect(page.getByLabel('Snapshot JSON', { exact: true })).toHaveValue('{"version":1}');
  await expect(page.getByText('Pairs: 1/8', { exact: true })).toBeVisible();
  await page.getByRole('button', { name: 'Restart', exact: true }).click();
  await expect(page.getByLabel('Board code', { exact: true })).toHaveValue('np1-4-1');
});

test('exports whole active milliseconds without pausing and restores pending progress paused', async ({ page }) => {
  await frozenPage(page);
  await loadBoard(page);
  await cards(page).nth(0).click();
  await cards(page).nth(1).click();
  await page.clock.runFor(250);
  const pending = await exported(page);
  await expect(page.getByRole('button', { name: 'Export snapshot', exact: true })).toBeFocused();
  expect(pending.elapsedMs).toBe(250);
  expect(pending.selection).toMatchObject({ kind: 'mismatch', remainingMs: 550 });
  const text = await page.getByLabel('Snapshot JSON', { exact: true }).inputValue();
  await page.clock.runFor(100);
  expect((await exported(page)).elapsedMs).toBe(350);
  await loadSnapshot(page, text);
  await expect(live(page)).toHaveText('Loaded snapshot. Select Resume to continue.');
  await expect(page.getByRole('button', { name: 'Load snapshot', exact: true })).toBeFocused();
  await cards(page).nth(0).focus();
  await page.keyboard.press('ArrowRight');
  await page.keyboard.press('ArrowDown');
  await expect(cards(page).nth(5)).toBeFocused();
  await page.keyboard.press('Enter');
  await page.keyboard.press('Space');
  await cards(page).nth(6).click({ force: true });
  await page.clock.runFor(5000);
  expect(await exported(page)).toEqual(pending);
  await cards(page).nth(5).focus();
  let resumeFocus = '';
  page.on('console', (message) => {
    if (message.text().startsWith('RESUME_FOCUS:')) resumeFocus = message.text().slice(13);
  });
  await page.getByRole('button', { name: 'Resume', exact: true }).evaluate((button) => {
    new MutationObserver(() => {
      if (!button.isConnected) console.info(`RESUME_FOCUS:${document.activeElement?.getAttribute('data-position')}`);
    }).observe(button.parentElement ?? button, { childList: true });
  });
  await page.getByRole('button', { name: 'Resume', exact: true }).click();
  await expect(cards(page).nth(5)).toBeFocused();
  await expect.poll(() => resumeFocus).toBe('5');
  await expect(page.getByRole('button', { name: 'Resume', exact: true })).toHaveCount(0);
  await page.clock.runFor(549);
  await expect(page.locator('.card--revealed')).toHaveCount(2);
  await page.clock.runFor(1);
  await page.keyboard.press('Enter');
  await expect(cards(page).nth(5)).toHaveAccessibleName(/revealed$/);
  await expect(page.locator('.card--revealed')).toHaveCount(1);
});

test('completed imports are static and do not write a best score', async ({ page }) => {
  await page.goto('/');
  await loadSnapshot(page, endingSnapshot(8, true));
  await expect(live(page)).toHaveText('Loaded completed snapshot.');
  await expect(page.getByRole('button', { name: 'Resume', exact: true })).toHaveCount(0);
  await expect(page.getByText('Best: none', { exact: true })).toBeVisible();
  await expect(page.locator('.win-banner')).not.toHaveClass(/celebrate/);
  expect(await page.locator('.win-banner').evaluate((node) => node.getAnimations().length)).toBe(0);
  await page.reload();
  await expect(page.getByText('Best: none', { exact: true })).toBeVisible();
  await expect(page.locator('.win-banner')).toHaveCount(0);
});

/work/tests/storage.spec.ts.content:
import { expect, test } from '@playwright/test';
import { cards, endingSnapshot, finish, loadBoard, loadSnapshot } from './support.ts';

test('persists only better local bests, current size and unrelated storage', async ({ page }) => {
  await page.goto('/');
  await page.evaluate(() => localStorage.setItem('unrelated-preference', 'keep'));
  for (const [moves, expected] of [[12, 13], [12, 13], [20, 13], [7, 8]]) {
    if (moves === undefined || expected === undefined) throw new Error('Missing fixture.');
    await loadSnapshot(page, endingSnapshot(moves));
    await page.getByRole('button', { name: 'Resume', exact: true }).click();
    await cards(page).nth(2).click();
    await cards(page).nth(6).click();
    await expect(page.getByText(`Best: ${expected}`, { exact: true })).toBeVisible();
  }
  await page.reload();
  await expect(page.getByText('Best: 8', { exact: true })).toBeVisible();
  await expect(page.getByText('Pairs: 0/8', { exact: true })).toBeVisible();
  await page.getByLabel('Grid size', { exact: true }).selectOption('6');
  await expect(page.getByText('Best: none', { exact: true })).toBeVisible();
  await page.reload();
  await expect(page.getByLabel('Grid size', { exact: true })).toHaveValue('6');
  await expect(cards(page)).toHaveCount(36);
  await loadBoard(page, 'np1-8-19');
  await page.reload();
  await expect(page.getByLabel('Grid size', { exact: true })).toHaveValue('8');
  expect(await page.evaluate(() => localStorage.getItem('unrelated-preference'))).toBe('keep');
  const saved = await page.evaluate(() => localStorage.getItem('neon-pairs.preferences.v1'));
  expect(saved).toBe('{"size":8,"bests":{"4":8}}');
});

for (const failure of ['read', 'write']) {
  test(`storage ${failure} failure leaves the game playable`, async ({ page }) => {
    await page.addInitScript((mode) => {
      if (mode === 'read') {
        Object.defineProperty(window, 'localStorage', { get: () => { throw new Error('Unavailable'); } });
      } else {
        Storage.prototype.setItem = () => { throw new Error('Quota exceeded'); };
      }
    }, failure);
    await page.goto('/');
    await loadBoard(page);
    await finish(page);
    await expect(page.getByText('Best: 8', { exact: true })).toBeVisible();
    await expect(page.getByRole('region', { name: 'Game complete' })).toBeVisible();
  });
}

test('ignores malformed preferences without loading active progress', async ({ page }) => {
  await page.goto('/');
  await page.evaluate(() => localStorage.setItem('neon-pairs.preferences.v1', '{broken'));
  await page.reload();
  await expect(page.getByLabel('Grid size', { exact: true })).toHaveValue('4');
  await expect(page.getByText('Best: none', { exact: true })).toBeVisible();
  await expect(page.getByText('Time: 0:00', { exact: true })).toBeVisible();
  await cards(page).first().click();
  await page.reload();
  await expect(page.locator('.card--revealed')).toHaveCount(0);
});

/work/tests/play.spec.ts.content:
import { expect, test } from '@playwright/test';
import { GRID_SIZES } from '../src/game/boardCode.ts';
import { cards, exported, finish, frozenPage, loadBoard, live } from './support.ts';

for (const size of GRID_SIZES) {
  test(`completes all pairs on ${size}x${size}`, async ({ page }) => {
    test.setTimeout(60000);
    await page.goto('/');
    await loadBoard(page, `np1-${size}-1`);
    await expect(cards(page)).toHaveCount(size * size);
    await finish(page, `np1-${size}-1`);
    await expect(page.getByRole('region', { name: 'Game complete' })).toBeVisible();
    await expect(page.getByText(`Moves: ${size * size / 2}`, { exact: true })).toBeVisible();
    await expect(page.getByText(`Pairs: ${size * size / 2}/${size * size / 2}`, { exact: true })).toBeVisible();
    await expect(page.locator('.card--matched')).toHaveCount(size * size);
    const completed = await exported(page);
    await page.waitForTimeout(50);
    expect((await exported(page)).elapsedMs).toBe(completed.elapsedMs);
  });
}

test('counts only second eligible reveals and expires before an equal-time action', async ({ page }) => {
  await frozenPage(page);
  await loadBoard(page);
  await cards(page).nth(0).click();
  await cards(page).nth(0).click();
  await expect(page.getByText('Moves: 0', { exact: true })).toBeVisible();
  await cards(page).nth(11).click();
  await expect(page.locator('.card--matched')).toHaveCount(2);
  await cards(page).nth(0).focus();
  await page.keyboard.press('Enter');
  await expect(page.getByText('Moves: 1', { exact: true })).toBeVisible();
  await cards(page).nth(1).click();
  await cards(page).nth(2).click();
  await expect(live(page)).toHaveText('No match. Cards close after a short pause.');
  await cards(page).nth(3).focus();
  await page.keyboard.press('Enter');
  await page.clock.runFor(799);
  await expect(page.locator('.card--revealed')).toHaveCount(2);
  await page.clock.runFor(1);
  await page.keyboard.press('Enter');
  await expect(page.locator('.card--revealed')).toHaveCount(1);
  await expect(cards(page).nth(3)).toHaveAccessibleName(/revealed$/);
  await expect(page.getByText('Moves: 2', { exact: true })).toBeVisible();
});

test('pauses active time and mismatch while the visibility lifecycle is hidden', async ({ page }) => {
  await frozenPage(page);
  await loadBoard(page);
  await cards(page).nth(0).click();
  await cards(page).nth(1).click();
  await page.clock.runFor(250);
  await page.evaluate(() => {
    Object.defineProperty(document, 'hidden', { configurable: true, value: true });
    document.dispatchEvent(new Event('visibilitychange'));
  });
  await page.clock.runFor(5000);
  const hidden = await exported(page);
  expect(hidden.elapsedMs).toBe(250);
  expect(hidden.selection).toMatchObject({ kind: 'mismatch', remainingMs: 550 });
  await page.evaluate(() => {
    Object.defineProperty(document, 'hidden', { configurable: true, value: false });
    document.dispatchEvent(new Event('visibilitychange'));
  });
  await page.clock.runFor(549);
  await expect(page.locator('.card--revealed')).toHaveCount(2);
  await page.clock.runFor(1);
  await cards(page).nth(2).focus();
  await page.keyboard.press('Enter');
  expect((await exported(page)).elapsedMs).toBe(800);
  await expect(page.locator('.card--revealed')).toHaveCount(1);
});

for (const label of ['New Game', 'Restart']) {
  test(`${label} invalidates an earlier mismatch and resets board focus`, async ({ page }) => {
    await frozenPage(page);
    await loadBoard(page);
    await cards(page).nth(0).click();
    await cards(page).nth(1).click();
    await page.clock.runFor(300);
    await page.getByRole('button', { name: label, exact: true }).click();
    await expect(page.getByRole('button', { name: label, exact: true })).toBeFocused();
    await expect(page.locator('.card[tabindex="0"]')).toHaveAttribute('data-position', '0');
    await expect(page.getByText('Moves: 0', { exact: true })).toBeVisible();
    await expect(page.locator('.card--revealed, .card--matched')).toHaveCount(0);
    const code = await page.getByLabel('Board code', { exact: true }).inputValue();
    expect(code === 'np1-4-1').toBe(label === 'Restart');
    await cards(page).nth(3).click();
    await page.clock.runFor(1000);
    await expect(cards(page).nth(3)).toHaveAccessibleName(/revealed$/);
    await expect(page.getByText('Moves: 0', { exact: true })).toBeVisible();
  });
}

